from pathlib import Path
import json,base64
p=Path(__file__).parent;r=p.parent
def enc(f):return 'data:image/png;base64,'+base64.b64encode(f.read_bytes()).decode()
assets={'reference':enc(r/'refs-spritecollab/Idle-Anim.png'),'sheet':enc(p/'Idle-Anim-PARTIEL.png'),'right':[enc(r/'revision-corpulence/repos-trois-quart-01.png'),enc(p/'repos-02-droite-local.png')],'left':[enc(r/'Huit-directions/avant-gauche.png'),enc(p/'repos-02-gauche-local.png')]}
h='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Repos · mouvement des bras</title><style>*{box-sizing:border-box}body{background:#14221c;color:#eff5e9;font:16px/1.5 system-ui;margin:0}main{max-width:1150px;margin:auto;padding:24px}.note{padding:14px;background:#453922;border-left:4px solid #ffc675}.controls{display:flex;gap:12px;align-items:end;margin:18px 0}button,select{background:#254435;color:#fff;border:1px solid #72977a;border-radius:6px;padding:9px;font:inherit}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}article{background:#253a2e;padding:14px;border-radius:9px}h2{font-size:16px;margin:0 0 12px}.stage{background:#cbdcc0;height:320px;display:grid;place-items:center}.stage canvas{width:100%;height:100%;image-rendering:pixelated}a{color:#b8efb1}@media(max-width:750px){.grid{grid-template-columns:1fr}}</style></head><body><main><h1>Repos · mouvement des bras</h1><p class="note">Essai sur les deux vues avant validées : les bras se replient vers la taille sur la seconde pose, comparée à Tsareena normale. La composition est limitée à la zone des bras ; les raccords et proportions restent à vérifier avant validation.</p><div class="controls"><label>Direction<br><select id="dir"><option value="1">Avant-droite</option><option value="7">Avant-gauche</option></select></label><button id="pause">Pause</button><button id="next">Image suivante</button><span id="count"></span></div><div class="grid"><article><h2>Tsareena normale · référence</h2><div class="stage"><canvas id="ref" width="400" height="320"></canvas></div></article><article><h2>Méga · détails de l’essai</h2><div class="stage"><canvas id="detail" width="400" height="320"></canvas></div></article><article><h2>Méga · planche à l’échelle</h2><div class="stage"><canvas id="sheet" width="400" height="320"></canvas></div></article></div><p><a download="Idle-Anim-PARTIEL-bras.png" href="__SHEET__">Télécharger la planche Idle partielle</a> · 2 directions renseignées sur 8, sans offsets ni ombres.</p><p>Référence SpriteCollab (baronessfaron) : 2 images de 30 ticks, à 60 Hz.</p></main><script>
const data=__DATA__;let imgs={};for(let k of ['reference','sheet']){imgs[k]=new Image;imgs[k].src=data[k]}for(let k of ['right','left'])imgs[k]=data[k].map(v=>{let i=new Image;i.src=v;return i});let paused=false,start=performance.now(),elapsed=0;const dr=document.querySelector('#dir');document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelector('#pause').textContent=paused?'Reprendre':'Pause';if(!paused)start=performance.now()-elapsed};document.querySelector('#next').onclick=()=>{paused=true;document.querySelector('#pause').textContent='Reprendre';elapsed=((Math.floor(elapsed/500)+1)%2)*500};dr.onchange=()=>{elapsed=0;start=performance.now()};function update(t){if(!paused)elapsed=t-start;let f=Math.floor(elapsed/500)%2,row=+dr.value,key=row===1?'right':'left';document.querySelector('#count').textContent='Image '+(f+1)+' / 2';for(let id of ['ref','detail','sheet']){let ctx=document.querySelector('#'+id).getContext('2d');ctx.clearRect(0,0,400,320);ctx.imageSmoothingEnabled=false;let im=id==='detail'?imgs[key][f]:imgs[id==='ref'?'reference':'sheet'];if(!im.complete||!im.naturalWidth)continue;if(id==='detail'){let scale=Math.min(300/im.height,360/im.width),w=im.width*scale,h=im.height*scale;ctx.drawImage(im,(400-w)/2,(320-h)/2,w,h)}else{ctx.drawImage(im,f*32,row*56,32,56,120,0,160,280)}}requestAnimationFrame(update)}requestAnimationFrame(update);
</script></body></html>'''
(p/'index.html').write_text(h.replace('__SHEET__',assets['sheet']).replace('__DATA__',json.dumps(assets)),encoding='utf8')
